#!/usr/bin/env python3
from pathlib import Path
import base64,gzip,subprocess,sys,tempfile
root=Path(sys.argv[1]).resolve()
patch=gzip.decompress(base64.b64decode(''))
with tempfile.NamedTemporaryFile(suffix='.patch') as f:
 f.write(patch); f.flush()
 subprocess.run(['git','apply','--check',f.name],cwd=root,check=True)
 subprocess.run(['git','apply',f.name],cwd=root,check=True)
checks=[]
def req(c,m):
 assert c,m; checks.append('PASS: '+m)
def rd(p): return (root/p).read_text()
req('appVersionCode = "4"' in rd('gradle/libs.versions.toml'),'versionCode 4')
req('appVersionName = "1.2.0-test4"' in rd('gradle/libs.versions.toml'),'versionName test4')
req('MediaServiceStarter' not in rd('fermata/src/auto/AndroidManifest.xml'),'Bluetooth auto-start receiver removed')
req('createConfigForDefaultDisplay' in rd('fermata/src/auto/java/me/aap/fermata/auto/ProjectionActivity.java'),'whole-display request retained')
req('RONAN_HIDE_PHONE_NAV", true' in rd('fermata/src/main/java/me/aap/fermata/ui/activity/MainActivityPrefs.java'),'navigation trim default on')
req('uniform vec4 uCrop' in rd('fermata/src/auto/java/me/aap/fermata/auto/AdaptiveMirrorRenderer.java'),'GPU crop included')
req('m.sourceY' in rd('fermata/src/auto/java/me/aap/fermata/auto/MirrorDisplay.java'),'touch remap included')
req('RONAN DESKTOP' in rd('fermata/src/auto/java/me/aap/fermata/auto/LauncherActivity.java'),'Ronan Desktop included')
req('MANUAL ACTIVATION' in rd('fermata/src/main/java/me/aap/fermata/ui/activity/RonanHubActivity.java'),'manual activation UI included')
(root/'RONAN-V4-SOURCE-CHECKS.txt').write_text('\n'.join(checks)+'\n')
print('\n'.join(checks))
